def get_product(pid):
    v = r.get(f'product:{pid}')
    if v: return json.loads(v)
    p = db.fetch_product(pid)
    r.setex(f'product:{pid}', 300, json.dumps(p))
    return p

def get(key):
    v = r.get(key)
    if v: return v
    if r.set(f'lock:{key}', 1, nx=True, ex=10):
        v = db_load(key); r.setex(key, 300, v); r.delete(f'lock:{key}')
        return v
    time.sleep(0.05)
    return r.get(key) or db_load(key)
